import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe {
    static int failures = 0;
    static void check(String name, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        if (!ok) { failures++; System.out.println("FAIL " + name + "\n  expected: " + expected + "\n  actual:   " + actual); }
        else System.out.println("ok   " + name);
    }
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (var e : els) sb.append(e.id()).append(' ');
        return sb.toString().trim();
    }
    public static void main(String[] args) {
        // 1. descendant / child / sibling scoping
        Document d = Jsoup.parse(
            "<div id=a><p id=a1><span id=a2></span></p></div>" +
            "<div id=b><p id=b1></p></div><span id=c></span><span id=e></span>");
        check("descendant", ids(d.select("div:has(span)")), "a");
        check("child not descendant-only", ids(d.select("div:has(> span)")), "");
        check("child", ids(d.select("div:has(> p)")), "a b");
        check("adjacent sibling", ids(d.select("div:has(+ span)")), "b");
        check("general sibling", ids(d.select("div:has(~ span)")), "a b");
        check("self not descendant", ids(d.select("div:has(div)")), "");

        // 2. nested has + :scope
        Document d2 = Jsoup.parse(
            "<div id=o1><section><p id=x><b></b></p></section></div>" +
            "<div id=o2><section><p></p></section></div>" +
            "<div id=o3><p><b></b></p></div>");
        check("nested has", ids(d2.select("div:has(section:has(> p > b))")), "o1");
        check("scope child", ids(d2.select("div:has(:scope > section)")), "o1 o2");
        check("scope nested", ids(d2.select("div:has(:has(b))")), "o1 o3");

        // 3. multiple branches: dedup + doc order
        Document d3 = Jsoup.parse(
            "<div id=m1><b></b></div><div id=m2><i></i></div><div id=m3><b></b><i></i></div><div id=m4></div>");
        check("or dedup order", ids(d3.select("div:has(b, i)")), "m1 m2 m3");
        check("or dedup order swapped", ids(d3.select("div:has(i, b)")), "m1 m2 m3");

        // 4. combine with :not, wildcard, escaped class, quoted attr
        Document d4 = Jsoup.parse(
            "<div id=n1 class=\"a.b\"><span data-x=\"a b\"></span></div>" +
            "<div id=n2><span data-x=\"ab\"></span></div>" +
            "<div id=n3 class=\"ab\"></div>");
        check("has + not", ids(d4.select("div:has(span):not(.a\\.b)")), "n2");
        check("escaped class", ids(d4.select("div.a\\.b:has(span)")), "n1");
        check("quoted attr", ids(d4.select("div:has(span[data-x=\"a b\"])")), "n1");
        check("wildcard", ids(d4.select("div:has(> *)")), "n1 n2");

        // 5. entities / whitespace in parsed DOM values
        Document d5 = Jsoup.parse("<div id=e1><p title=\"a&amp;b\"></p></div><div id=e2><p title=\"a&b\"></p></div>");
        check("entity attr", ids(d5.select("div:has(p[title=\"a&b\"])")), "e1 e2");

        // 6. query does not modify DOM
        Document d6 = Jsoup.parse("<div id=q><p>hi</p></div>");
        String before = d6.html();
        d6.select("div:has(> p)");
        d6.select("div:has(+ span)");
        check("no mutation", d6.html().equals(before), true);

        // 7. round-trip
        Document d7 = Jsoup.parse("<ul><li id=l1>one<ul><li id=l2>two</li></ul></li><li id=l3>three</li></ul>");
        String q = "li:has(> ul > li)";
        String r1 = ids(d7.select(q));
        Document d7b = Jsoup.parse(d7.html());
        String r2 = ids(d7b.select(q));
        check("roundtrip same", r1, r2);
        check("roundtrip value", r1, "l1");

        // 8. malformed html tolerance
        Document d8 = Jsoup.parse("<ul><li id=f1>one<li id=f2>two</ul><table><tr><td id=t1>x</td></tr></table><form id=fm1><form id=fm2></form></form>");
        check("unclosed li", ids(d8.select("li:has(+ li)")), "f1");
        check("table", ids(d8.select("table:has(td)")), "");
        check("table2", d8.select("table:has(td)").size(), 1);

        // 9. error semantics: bad branch fails whole query
        String[] bad = {"div:has(> )", "div:has()", "div:has(p,)", "div:has(p,,span)", "div:has((p)", "div:has(p", "div:has(>)"};
        for (String b : bad) {
            try {
                Jsoup.parse("<div><p></p></div>").select(b);
                check("throws: " + b, "no exception", "SelectorParseException");
            } catch (Selector.SelectorParseException e) {
                check("throws: " + b, "SelectorParseException", "SelectorParseException");
            } catch (Exception e) {
                check("throws: " + b, e.getClass().getSimpleName(), "SelectorParseException");
            }
        }
        // doc usable after failure
        Document d9 = Jsoup.parse("<div id=z><p id=z1></p></div>");
        try { d9.select("div:has(>)"); } catch (Selector.SelectorParseException ignored) {}
        check("usable after fail", ids(d9.select("div:has(p)")), "z");
        check("usable after fail plain", ids(d9.select("p")), "z1");

        // 10. state isolation across calls
        Document d10 = Jsoup.parse("<div id=s1><p></p></div><div id=s2></div>");
        check("repeat 1", ids(d10.select("div:has(p)")), "s1");
        check("repeat 2", ids(d10.select("div:has(p)")), "s1");
        Document d11 = Jsoup.parse("<div id=t1><p></p></div>");
        check("other doc", ids(d11.select("div:has(p)")), "t1");
        check("back again", ids(d10.select("div:has(p)")), "s1");

        // 11. empty results
        check("no match", Jsoup.parse("<div></div>").select("div:has(p)").size(), 0);
        check("empty doc", Jsoup.parse("").select("div:has(p)").size(), 0);

        // 12. sibling branch must not see inside subtree; descendant branch must not see siblings
        Document d12 = Jsoup.parse("<div id=w1><p></p></div><b id=b1></b>");
        check("sibling not descendant", ids(d12.select("div:has(+ b)")), "w1");
        Document d13 = Jsoup.parse("<div id=v1></div><p id=p1></p>");
        check("descendant not sibling", ids(d13.select("div:has(p)")), "");

        // 13. :has with attribute + sibling combinator combined
        Document d14 = Jsoup.parse(
            "<div id=g1><span class=x></span></div><em></em>" +
            "<div id=g2><span></span></div><em></em>" +
            "<div id=g3><span class=x></span></div>");
        check("attr+desc", ids(d14.select("div:has(span.x)")), "g1 g3");
        check("attr+sib", ids(d14.select("div:has(span.x) + em")), "g1");
        check("has with sib inside", ids(d14.select("div:has(span.x + em)")), "");
        Document d15 = Jsoup.parse("<div id=h1><span class=x></span><em></em></div>");
        check("internal + combinator", ids(d15.select("div:has(span.x + em)")), "h1");

        // 14. results remain traversable/editable
        Elements res = Jsoup.parse("<div id=k1><p>a</p></div><div id=k2><p>b</p></div>").select("div:has(p)");
        res.first().select("p").text();
        check("traversable", res.size(), 2);

        System.out.println(failures == 0 ? "\nALL OK" : "\n" + failures + " FAILURES");
    }
}
EOF
