import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe3 {
    static int failures = 0;
    static void check(String name, Object actual, Object expected) {
        boolean ok = String.valueOf(actual).equals(String.valueOf(expected));
        if (!ok) { failures++; System.out.println("FAIL " + name + "\n  expected: " + expected + "\n  actual:   " + actual); }
        else System.out.println("ok   " + name);
    }
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (var e : els) sb.append(e.id().isEmpty() ? e.tagName() : e.id()).append(' ');
        return sb.toString().trim();
    }
    public static void main(String[] args) {
        // nested :has with inner sibling anchor
        Document d1 = Jsoup.parse(
            "<div id=a><section id=a1></section><b></b></div>" +
            "<div id=c><section id=c1></section></div>");
        check("inner + anchor", ids(d1.select("div:has(section:has(+ b))")), "a");
        check("inner ~ anchor", ids(d1.select("section:has(~ b)")), "a1");

        // :scope deeper
        Document d2 = Jsoup.parse(
            "<div id=o1><p><b></b></p></div><div id=o2><p></p></div><div id=o3><section><p><b></b></p></section></div>");
        check("scope chain", ids(d2.select("div:has(:scope > p > b)")), "o1");
        check("scope descendant", ids(d2.select("div:has(:scope p b)")), "o1 o3");

        // mixed branches: child + sibling
        Document d3 = Jsoup.parse(
            "<div id=m1><p></p></div><em></em><div id=m2></div><em></em><div id=m3></div>");
        check("mixed branches", ids(d3.select("div:has(> p, + em)")), "m1 m2");

        // valid branch no match, other branch matches
        check("one empty branch", ids(d3.select("div:has(article, p)")), "m1");

        // nested error propagates
        String[] bad = {"div:has(span:has())", "div:has(span:has(>))", "div:has(p, span:has())"};
        for (String b : bad) {
            try {
                Jsoup.parse("<div><p></p></div>").select(b);
                check("throws: " + b, "no exception", "SelectorParseException");
            } catch (Selector.SelectorParseException e) {
                check("throws: " + b, "SelectorParseException", "SelectorParseException");
            }
        }

        // element-scoped select
        Document d4 = Jsoup.parse("<div id=root><div id=x><p></p></div><div id=y></div></div>");
        check("element scoped", ids(d4.selectFirst("#root").select("div:has(> p)")), "x");

        // round-trip structural equivalence (whitespace-normalized compare of text & hierarchy)
        Document d5 = Jsoup.parse("<div id=r1><p>a <b>bold</b></p><ul><li>1</li><li>2</li></ul></div><div id=r2><p>plain</p></div>");
        String q = "div:has(> p > b)";
        Elements first = d5.select(q);
        Document d5b = Jsoup.parse(d5.html());
        Elements second = d5b.select(q);
        check("roundtrip count", second.size(), first.size());
        check("roundtrip text", second.text(), first.text());
        check("roundtrip html eq", d5b.select(q).outerHtml(), first.outerHtml());

        // consecutive different selectors don't share state
        Document d6 = Jsoup.parse("<div id=s1><p></p></div><div id=s2><span></span></div>");
        check("seq a", ids(d6.select("div:has(p)")), "s1");
        check("seq b", ids(d6.select("div:has(span)")), "s2");
        check("seq a again", ids(d6.select("div:has(p)")), "s1");

        // parsed evaluator reused across docs
        var eval = Selector.parse("div:has(> p)");
        Document d7a = Jsoup.parse("<div id=e1><p></p></div>");
        Document d7b = Jsoup.parse("<div id=e2></div><div id=e3><p></p></div>");
        check("reused eval doc1", ids(d7a.select(eval)), "e1");
        check("reused eval doc2", ids(d7b.select(eval)), "e3");
        check("reused eval doc1 again", ids(d7a.select(eval)), "e1");

        // results editable & serializable after query
        Elements els = d6.select("div:has(span)");
        els.first().attr("data-t", "1");
        check("editable", d6.selectFirst("#s2").attr("data-t"), "1");

        // nested forms / unclosed tags tolerant tree
        Document d8 = Jsoup.parse("<form id=f1><div id=fd><input></div></form><p id=p1>tail");
        check("form tree", ids(d8.select("form:has(input)")), "f1");
        check("unclosed tail", ids(d8.select("div:has(input)")), "fd");

        System.out.println(failures == 0 ? "\nALL OK" : "\n" + failures + " FAILURES");
    }
}
